/**
 * Stand-in Web Push service for the fullstack E2E (playwright.fullstack.config.ts).
 * web-push only sends over HTTPS, so this receiver serves a self-signed cert
 * (generated by e2e-fullstack/global-setup.ts) and acts like a push service:
 *
 *   GET  /health       readiness probe (Playwright webServer)
 *   GET  /public-key   { p256dh, auth } — the "browser" subscription keys
 *   POST /push         push service delivery → captured + decrypted
 *   GET  /received     decrypted payloads [{ kind, title, body, link }]
 *
 * The spec registers a subscription whose endpoint points here, triggers a
 * real server event, then asserts on the decrypted payload — the same trick
 * web-push's own test suite uses.
 */

import { createServer } from 'https';
import { createECDH, randomBytes } from 'crypto';
import { readFileSync } from 'fs';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';
import { createRequire } from 'module';

// Resolve http_ece from server/node_modules (transitive dep of web-push).
const require = createRequire(join(dirname(fileURLToPath(import.meta.url)), '..', 'server', 'package.json'));
const http_ece = require('http_ece');

const PORT = Number(process.env.PUSH_RECEIVER_PORT ?? 9443);
const here = dirname(fileURLToPath(import.meta.url));
const { CERT_PATH, KEY_PATH, prepareCerts } = await import('./prepare-certs.mjs');
prepareCerts(); // webServer starts before globalSetup — self-generate if needed.

// The "browser's" ECDH keypair + auth secret; the spec fetches the public
// parts and registers them as the push subscription.
const ecdh = createECDH('prime256v1');
ecdh.generateKeys();
const AUTH_SECRET = randomBytes(16);

/** Decrypt a web-push payload (aes128gcm) with our private key. */
function decrypt(body) {
  return http_ece.decrypt(body, {
    version: 'aes128gcm',
    privateKey: ecdh,
    authSecret: AUTH_SECRET,
  });
}

const received = [];

function cors(res) {
  res.setHeader('Access-Control-Allow-Origin', '*');
  res.setHeader('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
}

const server = createServer(
  { key: readFileSync(KEY_PATH), cert: readFileSync(CERT_PATH) },
  (req, res) => {
    cors(res);
    if (req.method === 'OPTIONS') {
      res.writeHead(204);
      res.end();
      return;
    }
    const url = new URL(req.url, `https://localhost:${PORT}`);

    if (req.method === 'GET' && url.pathname === '/health') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify({ ok: true }));
      return;
    }

    if (req.method === 'GET' && url.pathname === '/public-key') {
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(
        JSON.stringify({
          p256dh: ecdh.getPublicKey().toString('base64url'),
          auth: AUTH_SECRET.toString('base64url'),
        })
      );
      return;
    }

    if (req.method === 'POST' && url.pathname === '/push') {
      const chunks = [];
      req.on('data', (chunk) => chunks.push(chunk));
      req.on('end', () => {
        received.push({ body: Buffer.concat(chunks), receivedAtMs: Date.now() });
        res.writeHead(201, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify({ ok: true }));
      });
      return;
    }

    if (req.method === 'GET' && url.pathname === '/received') {
      const payloads = received.map((entry) => {
        try {
          const parsed = JSON.parse(decrypt(entry.body).toString('utf8'));
          return {
            kind: parsed.kind,
            title: parsed.title,
            body: parsed.body,
            link: parsed.link,
            receivedAtMs: entry.receivedAtMs,
          };
        } catch (error) {
          return { error: `decrypt failed: ${error && error.message ? error.message : String(error)}` };
        }
      });
      res.writeHead(200, { 'Content-Type': 'application/json' });
      res.end(JSON.stringify(payloads));
      return;
    }

    res.writeHead(404);
    res.end();
  }
);

server.listen(PORT, () => {
  console.log(`[push-receiver] listening on https://localhost:${PORT}`);
});